import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Try it locally","description":"","frontmatter":{},"headers":[],"relativePath":"guide/demo.md","filePath":"guide/demo.md","lastUpdated":1787751651000}`),a={name:`guide/demo.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="try-it-locally" tabindex="-1">Try it locally <a class="header-anchor" href="#try-it-locally" aria-label="Permalink to “Try it locally”">​</a></h1><p>Before wiring up a real server, a hostname and a certificate, you can run a throwaway hub with three fake MCP servers and point an inspector at it. It takes one command and shows the parts that are hard to picture from a config file: the <code>/hub</code> aggregate, per-server endpoints, resource-bound tokens and idle sleep.</p><p>The setup lives in <a href="https://github.com/ni-c/mcp-hub/tree/main/demo" target="_blank" rel="noreferrer"><code>demo/</code></a> in the repository.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">git</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> clone</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://github.com/ni-c/mcp-hub.git</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">cd</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp-hub/demo</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">docker</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> compose</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> up</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">curl</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -s</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> localhost:7690/livez</span></span></code></pre></div><p>The hub is now on <a href="http://localhost:7690" target="_blank" rel="noreferrer">http://localhost:7690</a>, the login password is <code>demo</code>, and three servers are configured:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Tools</th></tr></thead><tbody><tr><td><code>/weather/mcp</code></td><td><code>list_stations</code>, <code>get_forecast</code></td></tr><tr><td><code>/tickets/mcp</code></td><td><code>list_tickets</code>, <code>get_ticket</code>, <code>create_ticket</code>, <code>list_statuses</code></td></tr><tr><td><code>/docs/mcp</code></td><td><code>search_docs</code>, <code>read_doc</code>, <code>list_docs</code></td></tr><tr><td><code>/hub</code></td><td>all three at once, through six meta-tools</td></tr></tbody></table><p>They answer from tables compiled into them — no network, no filesystem, no stored state — so the same call gives the same answer every time, and nothing a visitor does outlasts the request.</p><div class="warning custom-block"><p class="custom-block-title">Not a deployment template</p><p>The demo publishes its password, speaks plain HTTP, sleeps servers after a minute and keeps state in a volume nobody backs up. For a real host use <a href="https://github.com/ni-c/mcp-hub/blob/main/docker-compose.example.yml" target="_blank" rel="noreferrer"><code>docker-compose.example.yml</code></a> and the <a href="/guide/deployment">deployment guide</a>.</p></div><h2 id="mcp-inspector" tabindex="-1">MCP Inspector <a class="header-anchor" href="#mcp-inspector" aria-label="Permalink to “MCP Inspector”">​</a></h2><p>Start the <a href="https://github.com/modelcontextprotocol/inspector" target="_blank" rel="noreferrer">inspector</a> and leave it running:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @modelcontextprotocol/inspector</span></span></code></pre></div><p>Then open the pre-filled link:</p><p><a href="http://localhost:6274/?transport=http&amp;serverUrl=http://localhost:7690/hub" target="_blank" rel="noreferrer">http://localhost:6274/?transport=http&amp;serverUrl=http://localhost:7690/hub</a></p><p>The <code>serverUrl</code> and <code>transport</code> parameters fill the connection form; pressing <strong>Connect</strong> is still yours to do, because the inspector auto-connects only for a link that carries its own session token — which a link in a document cannot know. Replace <code>/hub</code> with <code>/weather/mcp</code> to connect to one server instead of the aggregate.</p><p>For authorization, either let the inspector run the OAuth flow (the password is <code>demo</code>) or paste a bearer token from <code>./token.sh hub</code> into the Authentication field.</p><h2 id="mcpjam" tabindex="-1">MCPJam <a class="header-anchor" href="#mcpjam" aria-label="Permalink to “MCPJam”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @mcpjam/inspector@latest</span></span></code></pre></div><p>Add a server, set the connection type to <strong>HTTP</strong> and enter <code>http://localhost:7690/hub</code>. Authorization is the same choice: OAuth with the password <code>demo</code>, or a token from <code>./token.sh hub</code>.</p><p>The hosted app at <a href="https://app.mcpjam.com" target="_blank" rel="noreferrer">app.mcpjam.com</a> cannot reach this demo. It connects to HTTPS endpoints only, and the demo is plain HTTP on localhost — use the local inspector above or the desktop app.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to “Tokens”">​</a></h2><p><code>demo/token.sh</code> mints API tokens through the <a href="/reference/admin-cli">admin CLI</a>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">./token.sh</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">            # a token for /hub</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">./token.sh</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> weather</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">    # a token for /weather/mcp</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">./token.sh</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --all</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">      # one per resource</span></span></code></pre></div><p>Tokens are <a href="/guide/security">bound to one resource</a>, which is easy to see here: a <code>hub</code> token gets a <code>401</code> from <code>/weather/mcp</code>. That is the default behaviour, not a misconfiguration.</p><h2 id="what-to-look-for" tabindex="-1">What to look for <a class="header-anchor" href="#what-to-look-for" aria-label="Permalink to “What to look for”">​</a></h2><ul><li><strong>The aggregate versus one server.</strong> Connected to <code>/hub</code>, a client carries six tool schemas — <code>list_servers</code>, <code>list_tools</code>, <code>get_tool_schema</code>, <code>call_tool</code>, <code>wake_server</code>, <code>sleep_server</code> — and reaches nine tools through them. Connected to <code>/tickets/mcp</code> it sees that one server, natively. See <a href="/guide/architecture">architecture</a>.</li><li><strong>Idle sleep.</strong> The demo sets <code>IDLE_TIMEOUT_MINUTES=1</code>, so you can watch it happen: leave a server alone for a minute or two — the sweep for idle servers runs once a minute, so it is not to the second — and <code>list_servers</code> reports it as <code>sleeping</code>. <code>list_tools</code> keeps answering from the tool cache, and the next <code>call_tool</code> wakes the server without the client noticing. <code>weather</code> is configured <code>&quot;keepAlive&quot;: true</code> and stays up. See <a href="/guide/on-demand">on-demand servers</a>.</li><li><strong>Hot reload.</strong> Edit <code>config/mcp.json</code> while the hub runs — no restart. See <a href="/guide/configuration#hot-reload">configuration</a>.</li><li><strong><code>/health</code>.</strong> State, restart count and tool count per server.</li></ul><h2 id="clean-up" tabindex="-1">Clean up <a class="header-anchor" href="#clean-up" aria-label="Permalink to “Clean up”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">docker</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> compose</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> down</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -v</span></span></code></pre></div><p><code>-v</code> removes the data volume with its tokens and client registrations, so the next start is a blank slate.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};